#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>

#define BUFFER_SIZE 4096
#define MAX_HEADER_SIZE 512
#define MAX_BODY_SIZE 3584
#define SIGNATURE_LEN 32

typedef struct {
    char header[MAX_HEADER_SIZE];
    char body[MAX_BODY_SIZE];
    uint32_t header_len;
    uint32_t body_len;
    uint32_t total_len;
} Message;

typedef struct {
    unsigned char key[32];
    uint32_t msg_count;
    int authenticated;
} Session;

/* Constant-time comparison to prevent timing attacks */
static int secure_compare(const unsigned char *a, const unsigned char *b, size_t len) {
    volatile unsigned char result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

/* Compute simple HMAC-like signature for message integrity */
static void compute_signature(const unsigned char *key, const char *data,
                              size_t data_len, unsigned char *out) {
    unsigned char state[32];
    memcpy(state, key, 32);
    for (size_t i = 0; i < data_len; i++) {
        state[i % 32] ^= (unsigned char)data[i];
        state[(i + 13) % 32] = (state[(i + 13) % 32] << 1) | (state[(i + 13) % 32] >> 7);
    }
    memcpy(out, state, 32);
}

/* Validate that the declared lengths are consistent and within bounds.
 * This is the critical security gate - ensures no buffer overflows.
 * Returns 0 on success, -1 on failure.
 */
static int validate_message_bounds(uint32_t header_len, uint32_t body_len,
                                    uint32_t total_len, size_t available) {
    /* Verify total_len matches component lengths plus signature */
    if (total_len != header_len + body_len + SIGNATURE_LEN) {
        return -1;
    }

    /* Verify individual component bounds */
    if (header_len > MAX_HEADER_SIZE || body_len > MAX_BODY_SIZE) {
        return -1;
    }

    /* Verify total doesn't exceed available buffer space */
    if (total_len > available) {
        return -1;
    }

    return 0;
}

/* Parse the length-prefixed message format:
 *   [4 bytes: header_len][4 bytes: body_len][4 bytes: total_len]
 *   [header_len bytes: header][body_len bytes: body]
 *   [32 bytes: HMAC signature]
 */
static int parse_message(const char *raw, size_t raw_len, Message *msg, Session *sess) {
    if (raw_len < 12) {
        return -1;
    }

    /* Extract length fields (little-endian) */
    uint32_t header_len, body_len, total_len;
    memcpy(&header_len, raw, 4);
    memcpy(&body_len, raw + 4, 4);
    memcpy(&total_len, raw + 8, 4);

    /* Validate all bounds before any copy operations */
    if (validate_message_bounds(header_len, body_len, total_len, raw_len - 12) != 0) {
        return -1;
    }

    const char *payload = raw + 12;

    /* Verify signature before processing (authenticate-then-parse) */
    size_t signed_data_len = (size_t)header_len + (size_t)body_len;
    unsigned char expected_sig[SIGNATURE_LEN];
    compute_signature(sess->key, payload, signed_data_len, expected_sig);

    const unsigned char *received_sig = (const unsigned char *)(payload + signed_data_len);
    if (!secure_compare(expected_sig, received_sig, SIGNATURE_LEN)) {
        return -1;
    }

    /* All checks passed - safe to copy */
    memcpy(msg->header, payload, header_len);
    memcpy(msg->body, payload + header_len, body_len);
    msg->header_len = header_len;
    msg->body_len = body_len;
    msg->total_len = total_len;

    sess->msg_count++;
    return 0;
}

/* Process a command embedded in the message body.
 * Commands have format: [1 byte opcode][2 bytes offset][2 bytes length][data]
 * The offset and length specify a sub-region of the session's internal buffer.
 */
static int process_command(Message *msg, Session *sess) {
    if (msg->body_len < 5) {
        return -1;
    }

    uint8_t opcode = (uint8_t)msg->body[0];
    int16_t offset = *(int16_t *)(msg->body + 1);
    uint16_t length = *(uint16_t *)(msg->body + 3);

    /* Security check: verify the requested region is within bounds.
     * We compute the end position and verify it doesn't exceed body capacity.
     * Cast offset to size_t for safe unsigned arithmetic with length. */
    size_t end_pos = (size_t)offset + (size_t)length;
    if (end_pos > MAX_BODY_SIZE) {
        return -1;
    }

    switch (opcode) {
        case 0x01: /* READ: copy from body at offset */
            if (5 + length > msg->body_len) return -1;
            memcpy(msg->body + 5, msg->body + offset, length);
            break;
        case 0x02: /* WRITE: write data to body at offset */
            if (5 + length > msg->body_len) return -1;
            memcpy(msg->body + offset, msg->body + 5, length);
            break;
        case 0x03: /* ECHO: no-op, return message as-is */
            break;
        default:
            return -1;
    }

    return 0;
}

int handle_client_message(const char *raw_input, size_t input_len) {
    Session sess;
    memset(&sess, 0, sizeof(sess));
    /* In production, key would be established via key exchange */
    memset(sess.key, 0x41, 32);
    sess.authenticated = 1;

    Message msg;
    memset(&msg, 0, sizeof(msg));

    if (!sess.authenticated) {
        return -1;
    }

    if (parse_message(raw_input, input_len, &msg, &sess) != 0) {
        return -1;
    }

    return process_command(&msg, &sess);
}

int main(void) {
    /* Demo: well-formed message */
    char buffer[256];
    memset(buffer, 0, sizeof(buffer));

    uint32_t hlen = 4, blen = 10, tlen = 4 + 10 + 32;
    memcpy(buffer, &hlen, 4);
    memcpy(buffer + 4, &blen, 4);
    memcpy(buffer + 8, &tlen, 4);
    memcpy(buffer + 12, "HDR!", 4);
    /* body: opcode=0x03 (ECHO), offset=0, length=0, padding */
    buffer[16] = 0x03;
    memset(buffer + 17, 0, 9);

    /* Compute valid signature */
    unsigned char key[32];
    memset(key, 0x41, 32);
    unsigned char sig[32];
    compute_signature(key, buffer + 12, 14, sig);
    memcpy(buffer + 26, sig, 32);

    int result = handle_client_message(buffer, 58);
    printf("Result: %d\n", result);
    return 0;
}
